package com.collegewise.controller;
import com.collegewise.dto.ApiDtos.*;import com.collegewise.entity.*;import com.collegewise.repository.*;import com.collegewise.security.JwtService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final ProfileRepository profiles;private final PasswordEncoder encoder;private final AuthenticationManager auth;private final JwtService jwt;public AuthController(UserRepository u,ProfileRepository p,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;profiles=p;encoder=e;auth=a;jwt=j;} @PostMapping("/register") ResponseEntity<Token> register(@Valid @RequestBody Register r){if(users.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=users.save(new User(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password()),Role.STUDENT));profiles.save(new StudentProfile(u));return ResponseEntity.status(HttpStatus.CREATED).body(token(u));} @PostMapping("/login") Token login(@Valid @RequestBody Login r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));return token(users.findByEmailIgnoreCase(r.email()).orElseThrow());} private Token token(User u){return new Token(jwt.issue(u.getEmail(),u.getRole().name()),"Bearer",u.getRole().name(),u.getName());} @PostMapping("/logout") Map<String,String> logout(){return Map.of("message","Remove the bearer token from the client to end this session.");} }
